        {
            get
            {
                if (_link == null)
                {
                    // Only generate links when all values are present
                    if (GeneratedArtifactStaticDependencies.ResourceLinksEnabled && IsReferenceFullyDefined())
                        _link = CreateLink();
                }

                return _link;
